    @Test
    public void getName_EmptyString_ReturnsEmptyString() {
        Tag tag = new Tag();
        Validate.equals("", tag.getName());
    }

    @Test
    public void getName_NonEmptyString_ReturnsNonEmptyString() {
        Tag tag = new Tag();
        tag.setName("Test");
        Validate.equals("Test", tag.getName());
    }

