    public void normalName_EmptyString_ReturnsEmptyString() {
        Tag tag = new Tag();
        Validate.equals("", tag.normalName());
    }

    @Test
    public void normalName_NonEmptyString_ReturnsNonEmptyString() {
        Tag tag = new Tag();
        tag.setName("Test");
        Validate.equals("test", tag.normalName());
    }

    @Test
    public void valueOf_EmptyString_ThrowsIllegalArgumentException() {
        AssertException.expect(IllegalArgumentException.class, () -> Tag.valueOf("", null));
    }

    @Test
    public void valueOf_NonEmptyString_ReturnsInstance() {
        String tagName = "test";
        ParseSettings settings = new ParseSettings();
        Tag tag = Tag.valueOf(tagName, settings);
        AssertTrue.assertTrue(tag instanceof Tag);
    }

